        sname=sc['name']
        # strip the req id prefix and the placeholder phrase
        body=sname.split('-',1)[1] if '-' in sname else sname
        body=body.replace('the requested workflow',' ')
        toks=re.findall(r'`([^`]+)`|([A-Z][A-Za-z0-9!]+)|(\bISO\b)', body)
        flat=[t for tup in toks for t in tup if t]
        # GIVEN content tokens
        given=' '.join(s['content'] for s in sc['steps'] if s['keyword']=='GIVEN')
        gtoks=re.findall(r'`([^`]+)`', given)
        # check mapping: every scenario-name token appears in the atomic description?
        desc=atomics.get(n['id'],'')
        miss=[t for t in flat if t not in desc and t.lower() not in desc.lower()]
        if miss:
            token_report.setdefault(n['id'],[]).append((sname, miss))
    for c in n.get('children',[]) or []:
        walk2(c)
walk2(d)

print("== 场景名幸存 token 未在 ATOMIC 描述中找到映射的 ==")
