for rid, entries in token_report.items():
    for sname, miss in entries:
        print(rid, '|', sname[:90], '| 未映射:', miss)

# Also extract surviving distinctive tokens from scenario names overall for the record
print()
print("== 全部场景名幸存 token（去重）==")
alltoks=set()
def walk3(n):
    for sc in (n.get('scenarios') or []):
        body=sc['name']
        body=body.replace('the requested workflow',' ')
        for t in re.findall(r'`([^`]+)`|[A-Z][A-Za-z0-9!]+|\bISO\b', body):
            if t: alltoks.add(t)
    for c in n.get('children',[]) or []:
        walk3(c)
walk3(d)
print(sorted(alltoks))

# GIVEN variants per requirement family
print()
print("== GIVEN 种子变体（按需求）==")
def walk4(n):
    givens=set()
    for sc in (n.get('scenarios') or []):
        for s in sc['steps']:
